const beforeReadingFlow109=bindReadingPanel;
bindReadingPanel=function(l){beforeReadingFlow109(l);const sections=l.sections||[];const current=sections.findIndex(x=>session.readingPage>=x.start&&session.readingPage<=x.end);const panel=$('#course-reading-panel');if(sections.length>1){panel.insertAdjacentHTML('afterbegin','<details class="section-menu"><summary><span class="section-caption">小节</span><span class="section-current">'+E(sections[current]?.title||sections[0].title)+'</span><span class="section-count">'+(current+1)+' / '+sections.length+'</span><svg class="section-chevron" viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg></summary><div class="section-options" role="group" aria-label="本课小节目录">'+sections.map((x,i)=>'<button class="section-option '+(i===current?'is-current':'')+'" data-section-index="'+i+'" '+(i===current?'aria-current="step"':'')+'><span class="section-number">'+String(i+1).padStart(2,'0')+'</span><span>'+E(x.title)+'</span>'+(i===current?'<span class="section-check" aria-hidden="true">✓</span>':'')+'</button>').join('')+'</div></details>');document.querySelectorAll('[data-section-index]').forEach(b=>b.onclick=()=>{session.readingPage=sections[Number(b.dataset.sectionIndex)].start;remember();panel.innerHTML=courseReading(l);bindReadingPanel(l)})}const startGroup=offset=>{session.practiceOffset=offset;session.qs=l.questions.slice(offset,offset+8);session.step=2;session.qi=0;session.chosen=null;session.revealed=false;remember();render()};$('#fresh-practice').onclick=()=>startGroup(0);panel.insertAdjacentHTML('beforeend','<div class="learning-actions"><button class="secondary" id="mark-read">阅读完成，返回目录</button>'+(['REC2-03','REC2-04','REC2-09','REC4-03'].includes(l.id)?'<button class="secondary" id="compare-practice">比较两种解释</button>':'')+'</div>');$('#mark-read').onclick=()=>{remember();state.readDone??={};state.readDone[l.id]=day();save();session=null;courseStage=l.stage;const related=DATA.lessons.find(x=>x.stage===l.stage&&x.display_number>l.display_number);$('#app').innerHTML='<section class="panel"><h1>本课阅读完成</h1><p>练习可按需要进行，不必一次做完全部题。</p><div class="learning-actions">'+(related?'<button class="primary" data-start="'+related.id+'">相关下一课：'+E(related.title)+'</button>':'')+'<button class="secondary" id="read-complete-return">返回目录</button></div></section>';bindStarts();$('#read-complete-return').onclick=()=>navigate('courses')};if($('#compare-practice'))$('#compare-practice').onclick=()=>comparePractice109(l)};
const beforeLessonFlow109=lessonView;
lessonView=function(){beforeLessonFlow109();if(session?.step===3&&session.id!=='review'){const l=DATA.lessons.find(l=>l.id===session.id),offset=(session.practiceOffset||0)+session.qs.length;const heading=document.querySelector('#app h1');if(heading)heading.textContent='本组练习完成';$('#app').insertAdjacentHTML('beforeend','<div class="learning-actions">'+(offset<l.questions.length?'<button class="primary" id="next-practice-group">继续下一组（还剩'+(l.questions.length-offset)+'题）</button>':'')+'<button class="secondary" id="group-reading-back">返回解析</button><button class="secondary" id="group-end">结束本次练习</button></div>');if($('#next-practice-group'))$('#next-practice-group').onclick=()=>{session.practiceOffset=offset;session.qs=l.questions.slice(offset,offset+8);session.step=2;session.qi=0;session.chosen=null;session.revealed=false;remember();render()};$('#group-reading-back').onclick=()=>{session.step=1;remember();render()};$('#group-end').onclick=()=>{remember();session=null;courseStage=l.stage;navigate('courses')}}};
function comparePractice109(l){const origin={...session};const variants=[{background:'材料已经核对完整，但还没有动手制作；本周就要分享。',correct:'A',reason:'主要阻碍是迟迟未动手，利用现有资源完成初稿更直接；核查方案仍有依据，但不是当前主要缺口。'},{background:'已有分享初稿，但资料出处尚未确认，表达也需要调整。',correct:'B',reason:'已经有初稿，关键缺口是证据和表达质量；先核对再调整比重新开始更回应背景。'},{background:'只知道要准备分享，没有说明材料和初稿目前怎样。',correct:'C',reason:'缺少材料是否齐全、是否已有初稿等条件；两种解释都可能，需要先确认背景。'}];let i=0;const explanations='<section class="panel"><h2>同一牌组</h2><div class="textbook-card-strip">'+['星币八','隐士','魔术师'].map(n=>'<figure>'+cardImage(n)+'<figcaption>'+E(n)+'</figcaption></figure>').join('')+'</div><p>现状：星币八；需要留意：隐士；行动建议：魔术师。均正位。</p><h3>A · 先完成一版</h3><p>持续练习，整理重点，利用现有材料做出一版分享。</p><h3>B · 先核对再打磨</h3><p>打磨已有内容，核对论据，再利用工具调整表达。</p><p class="tip">两种都是有画面依据的现代教学读法，比较的是适用条件。</p></section>';function show(){const v=variants[i];$('#app').innerHTML='<button class="link" id="comparison-back">← 返回本课</button><h1>两种解释，比较适用条件</h1>'+explanations+'<section class="panel"><h2>情境 '+(i+1)+' / 3</h2><p>'+E(v.background)+'</p>'+[['A','A更回应当前条件'],['B','B更回应当前条件'],['C','信息不足，需要确认背景']].map(([id,t])=>'<button class="option" data-compare-answer="'+id+'">'+t+'</button>').join('')+'<div id="comparison-feedback" aria-live="polite"></div><button class="primary hidden" id="comparison-next">'+(i<2?'换一个背景':'结束比较练习')+'</button></section>';$('#comparison-back').onclick=()=>{session=origin;render()};document.querySelectorAll('[data-compare-answer]').forEach(b=>b.onclick=()=>{state.comparisonAttempts??=[];state.comparisonAttempts.push({courseId:l.id,scenario:i,answer:b.dataset.compareAnswer,correct:b.dataset.compareAnswer===v.correct,date:day()});save();$('#comparison-feedback').textContent='参考答案：'+v.correct+'。'+v.reason;$('#comparison-next').classList.remove('hidden')});$('#comparison-next').onclick=()=>{if(++i<3)show();else{session=origin;render()}}}show()}
render();
